import sys

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0])
    rounds = []
    scores = {}

    idx = 1
    for _ in range(n):
        name = data[idx]
        score = int(data[idx + 1])
        idx += 2
        rounds.append((name, score))
        scores[name] = scores.get(name, 0) + score

    max_score = -float('inf')
    candidates = []
    for name, total in scores.items():
        if total > max_score:
            max_score = total
            candidates = [name]
        elif total == max_score:
            candidates.append(name)

    if len(candidates) == 1:
        print(candidates[0])
        return

    current_scores = {name: 0 for name in candidates}
    for name, score in rounds:
        if name in candidates:
            current_scores[name] += score
            if current_scores[name] >= max_score:
                print(name)
                return

if __name__ == "__main__":
    solve()
